import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { resolve } from 'node:path';
import { format, resolveConfig } from 'prettier';

export function renderSqlReadme(reference) {
  const intro = `# Query Language

<!-- Generated by npm run docs:sql from src/webclient/frontend/sql-reference.json. -->

The same tokenizer, parser, planner and executor power the CLI, webclient,
programmatic API and read-only conversational analytics. Open **SQL Reference**
beside the SQL editor or on the connection dialog. The reference is bundled
locally and requires neither an internet connection nor an open database.

Edit \`src/webclient/frontend/sql-reference.json\`, then run \`npm run docs:sql\`
to keep this README and the webclient reference synchronized.

## Entry points

\`npm run cli -- --data my.db --log my.db.log "SELECT * FROM articles LIMIT 10"\`

\`POST /api/query\` with \`{"sql":"SELECT * FROM articles LIMIT 10"}\` returns
\`{ rows, rowCount, kind, elapsedMs }\`. Mutations return one \`{id}\` row per
affected document. HTTP errors return \`{error}\` with status 400.

\`QueryLanguage\` is a thin facade over the existing database. It does not
open or commit databases itself:

\`\`\`ts
import { SimpleDbms } from '../database/simpledbms.mjs';
import { QueryLanguage } from './querylanguage.mjs';

// dataFile and logFile implement the existing File interface.
const db = await SimpleDbms.open(dataFile, logFile);
const sql = new QueryLanguage(db);
const rows = await sql.execute('SELECT category, COUNT(*) AS n FROM articles GROUP BY category');
const parsed = sql.parse('SELECT title FROM articles LIMIT 10');
await sql.executeParsed(parsed); // reuse an AST without parsing again
if (parsed.kind === 'select') sql.executeOnRows(preloadedRows, parsed);
await db.commit(); // explicit for successful direct writes
await db.close();
\`\`\`

AST and query-result types are re-exported from \`querylanguage.mts\`.
\`QueryMutationError\` in \`executor.mts\` exposes completed \`affectedIds\`
after a late UPDATE/DELETE failure. A successful commit is not statement rollback.

## Implementation map

| Component | Role |
| --- | --- |
| tokens.mts / parser.mts | One token-aware syntax path, source locations and AST validation |
| ast.mts | Statement, predicate, aggregate and result types |
| planner.mts | Compatible persisted index selection for conjunctions |
| executor.mts | Candidate cursors, full predicates, streaming reads and document mutations |
| expressions.mts | Strict comparisons, missing values, literal CONTAINS and LIKE |
| aggregator.mts / projection.mts | Incremental groups, aggregate state and final output aliases |
| SimpleDbms / DbmsBack | Existing record, compression, index, embedding and tombstone maintenance |

`;
  return (
    intro +
    reference.sections
      .map(
        (section) =>
          `## ${section.title}\n\n${section.paragraphs.join('\n\n')}\n\n${section.examples.map((example) => `\`\`\`sql\n${example}\n\`\`\`\n`).join('\n')}`,
      )
      .join('\n')
      .trimEnd() +
    '\n'
  );
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const reference = JSON.parse(
    await readFile(new URL('../src/webclient/frontend/sql-reference.json', import.meta.url), 'utf8'),
  );
  const target = new URL('../src/query/README.md', import.meta.url);
  const readme = await format(renderSqlReadme(reference), {
    ...(await resolveConfig(fileURLToPath(target))),
    parser: 'markdown',
  });
  if (process.argv.includes('--check')) {
    if ((await readFile(target, 'utf8')) !== readme)
      throw new Error('SQL reference README is stale. Run npm run docs:sql.');
  } else await writeFile(target, readme);
}
